import json,re,sys
from pathlib import Path
root=Path(sys.argv[1]);data={}
CASES={
 'operators':('The precedence pass that kept its scratch array',
  'Parsing "1 + 2 * 3" makes the precedence pass build a temporary operator list per block. The list items and the list struct were freed - but not the separately allocated backing array, so every populated operator block of every parsed formula lost 80 bytes. Both variants apply precedence identically (the value is 7 either way, byte-identical logs); only LeakSanitizer sees the difference: 160 bytes in 2 allocations lost before, no leaks at all after.'),
 'control':('Control: a bare constant',
  'A constant formula builds no operator list, so nothing reached the leaky path: both variants evaluate 42 with one calculation, and the complete log is byte-identical.')}
for mode,(label,explanation) in CASES.items():
 item={'label':label,'explanation':explanation}
 for phase in ('before','after'):
  raw=(root/f'{phase}-{mode}.log').read_text()
  entry={'raw':raw,'passed':'native-c/opblock-324 finished: 1/1 passed' in raw}
  for tag in ('RATING ','OUTCOME '):
   match=re.search(re.escape(tag)+r'(.*)',raw)
   entry[tag.split()[0].lower()]=match[1].strip() if match else None
  if mode=='operators':
   asan=(root/f'{phase}-asan-operators.log').read_text()
   entry['asan_raw']=asan
   summary=re.search(r'SUMMARY: AddressSanitizer: (.*)',asan)
   entry['asan_summary']=summary.group(1) if summary else 'no leaks reported'
  item[phase]=entry
 data[mode]=item
html='''<!doctype html><html lang="en"><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>The precedence pass that kept its scratch array</title><style>body{margin:0;background:#f4f1ea;color:#253a3c;font:18px/1.6 system-ui}main{max-width:1100px;margin:auto;padding:32px 24px}h1{font-size:40px;line-height:1.2}h2{font-size:24px}.cards{display:grid;grid-template-columns:1fr 1fr;gap:20px}.card{background:white;border:1px solid #cbd6d0;border-radius:12px;padding:24px;margin:18px 0}.cards .card{border-top:6px solid #648e80}.num{font-size:34px;font-weight:750}select,button{font:inherit;max-width:100%;padding:10px;border:1px solid #aabdb5;border-radius:7px;background:white}button{cursor:pointer;margin:14px 8px 0 0}button.active{background:#24685d;color:white}.summary{background:#e6eee6;padding:20px;border-left:5px solid #377367}pre{white-space:pre-wrap;overflow-wrap:anywhere;font:13px/1.5 monospace;max-height:330px;overflow:auto}details{background:white;padding:20px;margin:20px 0}summary{font-weight:700;cursor:pointer}@media(max-width:650px){.cards{grid-template-columns:1fr}h1{font-size:30px}}</style><main><p>Recorded native formula parses</p><h1>The precedence pass that kept its scratch array</h1><p>Every dynamic formula the Borg parses goes through a precedence pass that builds a temporary operator list for each block. The list items and the list struct were freed - but not the separately allocated backing array, so every populated operator block of every parsed formula leaked it, starting with the full formula file at startup.</p><section class="card"><label for="scenario">Choose a recorded situation</label><br><select id="scenario"></select><p id="explanation"></p></section><div class="cards"><section id="original" class="card"><h2>Original</h2><div class="num"></div><p class="state"></p><p class="leak"></p></section><section id="compared" class="card"><h2>Corrected</h2><div class="num"></div><p class="state"></p><p class="leak"></p></section></div><p class="summary" id="outcome"></p><h2>What the control establishes</h2><p>A bare constant builds no operator list: both variants evaluate 42 with byte-identical logs - and even the operator formula's functional output (value 7) is byte-identical; only the leak report changes.</p><details><summary>Experiment conditions and limits</summary><p>Native calculation machinery only (no game state needed): parse the constant-operator formula "1 + 2 * 3" and evaluate it; the leak proof is the same parse built with AddressSanitizer and run under LeakSanitizer. The lost allocations are 80 bytes per populated operator block per parse - a bounded leak at startup and per reinitialize, not a crash; no death or survival claim.</p></details><details><summary>Recorded native output</summary><h3>Original</h3><pre id="original-log"></pre><h3>Corrected</h3><pre id="compared-log"></pre></details><p>Canonical report: <a href="https://github.com/diegoami/neo-angband-tracker/issues/324">issue324</a>.</p></main><script>
const data=__DATA__;const select=document.getElementById('scenario');for(const [key,c] of Object.entries(data)){let o=document.createElement('option');o.value=key;o.textContent=c.label;select.append(o)}function draw(){let c=data[select.value];document.getElementById('explanation').textContent=c.explanation;for(const [panel,phase] of [['original','before'],['compared','after']]){let d=c[phase],p=document.getElementById(panel);let r=d.rating||'';let m=r.match(/formula_value=(\\d+)/);let mc=r.match(/control_value=(\\d+)/);if(m){p.querySelector('.num').textContent='1 + 2 * 3 = '+m[1];p.querySelector('.leak').textContent='LeakSanitizer on the same parse: '+d.asan_summary}else if(mc){p.querySelector('.num').textContent='42 = '+mc[1];p.querySelector('.leak').textContent=''}else{p.querySelector('.num').textContent='n/a'}p.querySelector('.state').textContent=d.outcome||'';document.getElementById(panel+'-log').textContent=d.raw}document.getElementById('outcome').textContent=select.value==='operators'?'Both variants compute 7 with byte-identical output - but the original loses 160 bytes in 2 backing-array allocations on the way; the correction frees them, and LeakSanitizer reports no leaks at all.':'The constant parse was never at risk: 42 either way, byte for byte.';}select.addEventListener('change',draw);draw();</script></html>'''
(root/'replay.html').write_text(html.replace('__DATA__',json.dumps(data).replace('<','\\u003c')))
(root/'replay-data.json').write_text(json.dumps(data,indent=2)+'\n')
print('Open in your browser:',root/'replay.html')
